import CryptoKit
import Foundation
import GlideCore

// Reproduces docs/test-vectors.json (generated by tools/gen_vectors.py) byte-for-byte.
// Usage: glide-selftest [path/to/test-vectors.json]

var failures = 0
func check(_ ok: Bool, _ what: String) {
    if ok { print("  ok   \(what)") } else { failures += 1; print("  FAIL \(what)") }
}

struct Vectors: Decodable {
    struct Record: Decodable { let dir: String; let counter: Int; let plaintext: String; let record: String }
    let password, client_private, host_private, client_handshake, host_handshake, pw_key, shared, c2s_key, s2c_key: String
    let records: [Record]
}

func run() throws {
    let path = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "../docs/test-vectors.json"
    let v = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: URL(fileURLWithPath: path)))

    let cpriv = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: Data(hex: v.client_private)!)
    let hpriv = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: Data(hex: v.host_private)!)
    let chRaw = Data(hex: v.client_handshake)!, hhRaw = Data(hex: v.host_handshake)!

    let ch = try Handshake.ClientHello.decode(chRaw)
    check(ch.publicKey == cpriv.publicKey.rawRepresentation, "client handshake pubkey")
    check(ch.encoded == chRaw, "client handshake re-encode")
    let hh = try Handshake.HostHello.decode(hhRaw)
    check(hh.publicKey == hpriv.publicKey.rawRepresentation, "host handshake pubkey")
    check(hh.encoded == hhRaw, "host handshake re-encode")

    let pwk = Handshake.passwordKey(v.password, salt: hh.salt)
    check(pwk.hex == v.pw_key, "PBKDF2 password key")
    let shared = try Handshake.sharedSecret(privateKey: cpriv, peerPublic: hh.publicKey)
    check(shared.hex == v.shared, "X25519 shared secret")
    check(try Handshake.sharedSecret(privateKey: hpriv, peerPublic: ch.publicKey) == shared, "X25519 symmetric")

    let keys = Handshake.deriveKeys(shared: shared, passwordKey: pwk, clientHandshake: chRaw, hostHandshake: hhRaw)
    check(keys.c2s.withUnsafeBytes { Data($0) }.hex == v.c2s_key, "HKDF c2s key")
    check(keys.s2c.withUnsafeBytes { Data($0) }.hex == v.s2c_key, "HKDF s2c key")

    let sealC = RecordCipher(key: keys.c2s), sealS = RecordCipher(key: keys.s2c)
    let openC = RecordCipher(key: keys.c2s), openS = RecordCipher(key: keys.s2c)
    for rec in v.records {
        let pt = Data(hex: rec.plaintext)!
        let sealed = rec.dir == "c2s" ? sealC.seal(pt) : sealS.seal(pt)
        check(sealed.hex == rec.record, "record \(rec.dir)#\(rec.counter) bytes")
        let opened = try (rec.dir == "c2s" ? openC : openS).open(sealed.dropFirst(4))
        check(opened == pt, "record \(rec.dir)#\(rec.counter) decrypt")
    }

    if case let .hello(_, caps, vw, vh, _, fps, name) = try ClientMessage.decode(Data(hex: v.records[0].plaintext)!) {
        check(caps == [.hevc420, .hevc444, .h264] && vw == 3840 && vh == 2160 && fps == 60 && name == "test-client", "ClientHello fields")
    } else { check(false, "ClientHello decode") }
    if case let .mouseMove(x, y) = try ClientMessage.decode(Data(hex: v.records[1].plaintext)!) {
        check(x == 0.25 && y == 0.75, "MouseMove fields")
    } else { check(false, "MouseMove decode") }
    if case let .serverHello(_, name, cfg) = try HostMessage.decode(Data(hex: v.records[2].plaintext)!) {
        check(name == "test-host" && cfg == VideoConfig(width: 2560, height: 1440, codec: .hevc, chroma: .yuv420, scale: 2.0), "ServerHello fields")
        check(HostMessage.serverHello(version: 1, hostName: name, config: cfg).encoded.hex == v.records[2].plaintext, "ServerHello re-encode")
    } else { check(false, "ServerHello decode") }

    // Wrong key must fail to decrypt.
    let a = RecordCipher(key: SymmetricKey(size: .bits256)), b = RecordCipher(key: SymmetricKey(size: .bits256))
    check((try? b.open(a.seal(Data([1, 2, 3])).dropFirst(4))) == nil, "wrong key rejected")

    // Keymap: letters, digits, Enter..Space, punctuation, modifiers all mapped.
    var missing: [String] = []
    for u in Array(UInt16(0x04)...0x38) + Array(UInt16(0xE0)...0xE7) where HIDKeymap.macKeyCode(forUsage: u) == nil {
        missing.append(String(format: "0x%02x", u))
    }
    check(missing.isEmpty, "keymap coverage \(missing)")
}

do { try run() } catch { failures += 1; print("  FAIL threw \(error)") }
print(failures == 0 ? "ALL TESTS PASSED" : "\(failures) FAILURE(S)")
exit(failures == 0 ? 0 : 1)
